def admin():
    body='''<section class="page-intro admin-intro"><div class="wrap narrow"><div class="eyebrow">PRIVATE EDITORIAL WORKSPACE</div><h1>Review before <span class="gradient-text">release.</span></h1><p>This area is for the Aptitude Mind Plus owner. Community submissions never publish without your approval.</p></div></section><section class="section compact-section"><div class="wrap admin-wrap"><div class="admin-login form-card" data-admin-login><div class="form-head"><h2>Reviewer access</h2><p>Enter the administrator password configured privately in your hosting dashboard.</p></div><form data-admin-login-form><label>Password<input type="password" name="password" required minlength="12" autocomplete="current-password" placeholder="Administrator password"></label><div class="form-notice" data-admin-login-message aria-live="polite"></div><button class="button button-primary full-button" type="submit">Sign in securely ↗</button></form></div><section class="admin-panel" data-admin-panel hidden><div class="admin-top"><div><div class="eyebrow">MODERATION DESK</div><h2>Questions & enquiries</h2></div><button type="button" class="button button-light" data-admin-logout>Sign out</button></div><div class="tab-set"><button class="tab active" data-admin-tab="pending" aria-pressed="true">Pending questions <b data-pending-counter>0</b></button><button class="tab" data-admin-tab="published" aria-pressed="false">Reviewed</button><button class="tab" data-admin-tab="applications" aria-pressed="false">Course enquiries</button></div><div data-admin-content><div class="empty-state">Loading submissions…</div></div><div class="form-notice" data-admin-notice role="status" aria-live="polite"></div></section></div></section>'''
    html=shell('admin.html','Admin Review','Private approval and review dashboard for submitted questions and course enquiries.',body)
    return html.replace('<meta name="theme-color"','<meta name="robots" content="noindex,nofollow"><meta name="theme-color"',1)

def privacy():
    body='''<section class="page-intro"><div class="wrap narrow"><div class="eyebrow">PRIVACY & CONTRIBUTIONS</div><h1>Trust matters <span class="gradient-text">here.</span></h1><p>We keep the initial service intentionally simple and collect only what is necessary to review questions or reply to class enquiries.</p></div></section><section class="section compact-section"><div class="wrap legal-wrap"><article><h2>Question submissions</h2><p>We collect the question, optional photo, proposed answer, source details and any optional name or email you provide. Submissions are held privately until reviewed. We may reject them, and we publish no contributor email addresses. Please do not upload personal student data or copyrighted content without permission.</p><h2>Course enquiries</h2><p>We collect contact details and course preferences solely to respond to the request. A parent or guardian should enquire on behalf of children under 18. No payment information is collected on this website.</p><h2>Content quality and copyright</h2><p>Community approval does not make a question an official previous-year exam question. We assign an official label only after checking the cited exam source. Contributors should upload only material they are authorised to share. For rights concerns, contact the site owner through the course enquiry channel once that service is active.</p><h2>Data storage and retention</h2><p>When the site backend is activated, submitted information is stored in its configured Cloudflare D1 database. Approved questions may be made public without submitter contact details. The owner should regularly review and delete unnecessary or rejected personal data; a specific retention schedule has not yet been set.</p><h2>Security</h2><p>Administrative review requires private credentials. Public pages use encrypted HTTPS when deployed through Cloudflare Pages. No website can promise perfect security. Do not submit passwords, identity numbers, private exam IDs or payment card information.</p><h2>Before the site launches</h2><p>The operator must supply a working contact method, review applicable Indian privacy obligations and school/child-protection rules, and finalise a retention policy. This page is a starter notice, not legal advice.</p></article></div></section>'''
    return shell('privacy.html','Privacy & Content Policy','How Aptitude Mind Plus collects and reviews questions and course enquiries.',body)

def missing():
    return shell('404.html','Page not found','The requested page is not available.',f'''<section class="page-intro"><div class="wrap narrow center"><div class="eyebrow">404 / NOT FOUND</div><h1>Not every path leads <span class="gradient-text">somewhere.</span></h1><p>This page doesn't exist or may have moved. Let's get you back to learning.</p>{btn('Return home','index.html')}</div></section>''')

allpages={'index.html':home(),'concepts.html':concepts(),'courses.html':courses(),'practice.html':practice(),'pyqs.html':pyqs(),'submit.html':submit(),'tutoring.html':tutoring(),'admin.html':admin(),'privacy.html':privacy(),'404.html':missing()}
for name,content in allpages.items():
    (ROOT/name).write_text(content,encoding='utf-8')
print('Generated',len(allpages),'pages')